-- Si el cliente ya está en la app (mismo email, teléfono o nombre) se usa ese; si no, se crea.
-- Los pedidos entran directo en su etapa (no se crean tareas de etapas ya pasadas).

create or replace function pg_temp.cliente(p_nombre text, p_tel text, p_email text, p_dni text, p_dir text, p_loc text, p_cp text) returns uuid
language plpgsql as $$
declare v uuid; v_tel text := right(regexp_replace(coalesce(p_tel, ''), '\D', '', 'g'), 8);
begin
  select id into v from public.clientes
   where (p_email is not null and lower(email) = lower(p_email))
      or (length(v_tel) = 8 and right(regexp_replace(coalesce(telefono, ''), '\D', '', 'g'), 8) = v_tel)
      or lower(trim(nombre)) = lower(trim(p_nombre))
   order by creado_en limit 1;
  if v is not null then
    update public.clientes set
      telefono = coalesce(telefono, p_tel), email = coalesce(email, p_email), dni = coalesce(dni, p_dni),
      direccion = coalesce(direccion, p_dir), localidad = coalesce(localidad, p_loc), codigo_postal = coalesce(codigo_postal, p_cp)
    where id = v;
    return v;
  end if;
  values (trim(p_nombre), p_tel, p_email, p_dni, p_dir, p_loc, p_cp) returning id into v;
  return v;
end $$;

create or replace function pg_temp.vendedor(p_alias text) returns uuid
language sql as $$
  select id from public.equipo
  where p_alias is not null and (lower(alias_planilla) = lower(p_alias) or lower(split_part(nombre, ' ', 1)) = lower(p_alias))
  order by coalesce(lower(alias_planilla) = lower(p_alias), false) desc, activo desc limit 1
$$;

